sys_script_include.script:
var BaseRegistrationUtils = Class.create();
BaseRegistrationUtils.prototype = {
    initialize: function() {},

    getAvailableBases: function() {

        var userId = gs.getUserID();

        var reg = new GlideRecord('x_2060759_base_m_0_registration'); 
        reg.addQuery('opened_by', userId); 
        reg.addQuery('state', '!=', 'rejected'); 
        reg.addNotNullQuery('base');
        reg.setLimit(1);
        reg.query();

        if (reg.next()) {
            return 'sys_idISEMPTY';
        }

        return 'occupied_capacity<maximum_capacity';
    },

    type: 'BaseRegistrationUtils'
};
